-- Project schema owner: Run Statement once. Installs a NEW application ID, never overwrites by ID.
-- Select the complete DECLARE through final END; block, excluding the final slash (/).
-- Run Statement opens the required target/application-ID bind prompts.
-- Target binds may be left blank for KCV_LAB / KCV_KNOWLEDGE / KCV-EXPLORER.
DECLARE
 l_app_id NUMBER;
 l_count NUMBER;
 l_schema VARCHAR2(128):=NVL(UPPER(TRIM(:KCV_SCHEMA)),'KCV_LAB');
 l_workspace VARCHAR2(128):=NVL(UPPER(TRIM(:KCV_WORKSPACE)),'KCV_KNOWLEDGE');
 l_alias VARCHAR2(128):=NVL(UPPER(TRIM(:KCV_APP_ALIAS)),'KCV-EXPLORER');
BEGIN
 IF NOT REGEXP_LIKE(l_schema,'^KCV_[A-Z0-9_]{1,26}$','c')
  OR NOT REGEXP_LIKE(l_workspace,'^[A-Z][A-Z0-9_]{0,29}$','c')
  OR NOT REGEXP_LIKE(l_alias,'^[A-Z][A-Z0-9-]{0,50}$','c') THEN
  RAISE_APPLICATION_ERROR(-20165,'Use valid project schema, workspace and application alias names');END IF;
 IF SYS_CONTEXT('USERENV','CURRENT_SCHEMA')<>l_schema
  OR SYS_CONTEXT('USERENV','SESSION_USER')<>l_schema
  OR USER<>SYS_CONTEXT('USERENV','SESSION_USER')
  OR USER IN ('ADMIN','SYS','SYSTEM') THEN
   RAISE_APPLICATION_ERROR(-20160,'Connect as the intended parsing schema owner');END IF;
 EXECUTE IMMEDIATE 'SELECT COUNT(*) FROM kcv_schema_migrations WHERE migration_id=:1 AND product_version=:2 AND phase=:3'
  INTO l_count USING '2.0.0-c3-r7-ready','2.0.0','COMPLETE';
 IF l_count<>1 THEN RAISE_APPLICATION_ERROR(-20163,'Apply and verify the v2 personal journey schema migration before importing this app');END IF;
 SELECT COUNT(*) INTO l_count FROM user_objects
  WHERE object_name IN ('KCV_ACCESS','KCV_PERSONAL_CONTEXT_API','KCV_PERSONAL_JOURNEY','KCV_SCENARIO','KCV_TRACE','KCV_APEX','KCV_CONTEXT_DELETE','KCV_CONTEXT_SEARCH')
    AND object_type IN ('PACKAGE','PACKAGE BODY') AND status='VALID';
 IF l_count<>16 THEN RAISE_APPLICATION_ERROR(-20164,'Required personal journey, conversation, deletion and search APIs must compile before app installation');END IF;
 APEX_APPLICATION_INSTALL.SET_WORKSPACE(l_workspace);
 APEX_APPLICATION_INSTALL.SET_SCHEMA(l_schema);
 SELECT COUNT(*) INTO l_count FROM apex_applications
  WHERE workspace=l_workspace AND UPPER(alias)=l_alias;
 IF l_count<>0 THEN RAISE_APPLICATION_ERROR(-20166,'Application alias already exists; use the reviewed upgrade path or a different alias');END IF;
 APEX_APPLICATION_INSTALL.GENERATE_APPLICATION_ID;
 APEX_APPLICATION_INSTALL.GENERATE_OFFSET;
 l_app_id:=APEX_APPLICATION_INSTALL.GET_APPLICATION_ID;
 APEX_APPLICATION_INSTALL.SET_APPLICATION_ALIAS(l_alias);
begin
